delete from t_flow_tag_relation
where flow_definition_id = #{flowDefinitionId}
  and app_code = #{appCode}

delete from t_flow_tag_relation
where tag_id = #{flowTagId}
  and app_code = #{appCode}

mapper.select:
select t1.id, t1.app_code, t1.tag_id, t1.flow_definition_id, t2.name as tagName from t_flow_tag_relation t1 inner join t_flow_tag t2 on t1.tag_id=t2.id where t1.flow_definition_id in
#{item}
and (t2.access_type = 'public' or (t2.access_type = 'private' and t2.created_by = #{userId})) order by t2.created_at
